def chapter_key(subject, folder):
    number = folder.rsplit("-", 1)[-1]
    if subject == "Management" and number == "11":
        return "11-communication" if folder.startswith("Communication") else "11-ei"
    return number


def load_tasks():
    groups = {}
    seen = set()
    for line in TASK_DATA.strip().splitlines():
        fields = line.split("|")
        if len(fields) != 5:
            raise ValueError(f"Expected five topic-task fields: {line}")
        subject, chapter, kind, title, demand = fields
        if kind not in {"S", "C", "A"} or not title or not demand:
            raise ValueError(f"Invalid study task: {line}")
        key = (subject, chapter)
        identity = (*key, title)
        if identity in seen:
            raise ValueError(f"Duplicate study task: {identity}")
        seen.add(identity)
        groups.setdefault(key, []).append(dict(kind=kind, title=title, demand=demand))
    return groups


def make_prompt(subject, chapter, task):
    kind = {"S": "Static explanation", "C": "Current source verification", "A": "Applied practice"}[task["kind"]]
    lines = [
        "Prepare explained study notes for RBI Grade B Phase II (2027 preparation).",
        f"Subject: {subject}. Chapter: {chapter}.",
        f"Selected topic: {task['title']}. Task type: {kind}.",
        f"Specific task: {task['demand']}",
        "Stay within this selected topic. Teach the explanation directly; do not return only a reading list or source links.",
        "Check whether any current affairs are directly related to this selected topic and include "
        "explained notes on relevant developments, why they matter and their connection to the static "
        "concept or exam task. Do this even for a static or applied-practice topic. If no relevant "
        "development is found in the sources checked, say so without inventing a connection; if you "
        "cannot check, state that limitation rather than claiming there are no updates. For English, "
        "keep external current-affairs evidence separate from passage-based answers.",
        "Where useful, include a mind map, infographic, flowchart or comparison/data table to improve "
        "understanding and memorisation. Choose formats suited to the topic rather than forcing every "
        "format. Provide the actual visual or table content, not just a suggestion to create it; if "
        "image rendering is unavailable, use a readable text mind map, labelled flowchart or Markdown "
        "table. Use concise labels and retrieval cues, preserve important qualifications, and label "
        "units, dates and sources for factual data; do not invent statistics for a visual.",
    ]
    if subject == "English":
        lines.append(
            "Give the requested original passage/draft/outline or model response, explicit workings such as "
            "word counts where required, and a fully revealed explanation. Do not reproduce protected source "
            "passages. Separate passage-based answers from outside facts. Use a diagnostic checklist, not an "
            "invented official RBI score or rubric."
        )
    else:
        lines.append(
            "Output: (1) numbered explanations answering every subpart, "
            "(2) a comparison/data table or labelled causal sequence suited to this topic, "
            "(3) one worked numerical example or concrete case with assumptions, "
            "(4) common confusions and exceptions, (5) three ORIGINAL practice MCQs with every answer "
            "and explanation revealed, and one 10- or 15-mark descriptive question with an answer outline. "
            "Label generated practice as original, not a previous-year question."
        )
    lines.append(
        "State the as-of date you can actually verify. Use primary RBI/SEBI/Ministry/MoSPI/official "
        "publisher sources as applicable; give document title, edition/reference period, release/effective "
        "date and source URL. Separate historical rule, announcement/proposal, operative rule and verified "
        "current status. If browsing or necessary source pages are unavailable, explicitly mark missing "
        "facts unverified and request the relevant document; never invent a latest edition, limit, "
        "rank, scheme availability or legal provision. Do not assume a 2027 rule is already known."
    )
    lines.append(
        "When supplied, check relevant material in all four preparation collections: "
        "CurrentAffairs-Monthly, Reports_NationalAndInternational, "
        "SchemesAndGovernmentPortals and StaticGK. Reconcile related evidence across them, "
        "then verify factual claims against primary sources. Explicitly identify unavailable "
        "collections; do not claim to have scanned files you cannot access."
    )
    if task["kind"] != "C":
        lines.append(
            "Use clearly labelled invented numbers/people for examples. Cite reliable sources for factual "
            "or theoretical attributions and distinguish established definitions from debated interpretation. "
            "If using any current rule or statistic, state its verified date/source or mark it unverified."
        )
    lines.append(
        "If supplied notes conflict, identify the exact conflict and retain the uncertainty rather than "
        "silently selecting a value. End with five short recall questions and fully revealed answers."
    )
    return "\n\n".join(lines)
